result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/nllite.py", "content": "#!/usr/bin/env python3
"""nllite.py -- a minimal `nl` clone.

Options:
  -bt        Number only non-blank lines (default).
  -ba        Number every line, including blanks.
  -w WIDTH   Right-justify line numbers in WIDTH columns (default 6).
  -s SEP     Separator printed after each number (default tab).

Usage: nllite.py [-ba|-bt] [-w WIDTH] [-s SEP] [FILE]
Reads stdin if no FILE (or FILE is "-").
"""

import sys


def parse_args(argv):
    body = "t"
    width = 6
    sep = "\t"
    files = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "-ba":
            body = "a"
        elif arg == "-bt":
            body = "t"
        elif arg == "-w":
            i += 1
            if i >= len(argv):
                raise SystemExit("nllite: option '-w' requires an argument")
            try:
                width = int(argv[i])
            except ValueError:
                raise SystemExit(f"nllite: invalid width: {argv[i]!r}")
            if width < 1:
                raise SystemExit(f"nllite: invalid width: {argv[i]!r}")
        elif arg.startswith("-w") and len(arg) > 2:
            try:
                width = int(arg[2:])
            except ValueError:
                raise SystemExit(f"nllite: invalid width: {arg!r}")
        elif arg == "-s":
            i += 1
            if i >= len(argv):
                raise SystemExit("nllite: option '-s' requires an argument")
            sep = argv[i]
        elif arg.startswith("-s") and len(arg) > 2:
            sep = arg[2:]
        elif arg == "--":
            files.extend(argv[i + 1:])
            break
        else:
            files.append(arg)
        i += 1
    return body, width, sep, files


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    body, width, sep, files = parse_args(argv)
    stream = sys.stdin
    if files:
        path = files[0]
        stream = open(path, "r") if path != "-" else sys.stdin

    try:
        number = 0
        for line in stream:
            blank = not line.strip("\r\n").strip()
            if body == "a" or not blank:
                number += 1
                prefix = f"{number:{width}}{sep}"
                print(prefix + line, end="" if line.endswith("\n") else "\n")
            else:
                print(line, end="" if line.endswith("\n") else "\n")
    finally:
        if stream is not sys.stdin:
            stream.close()


if __name__ == "__main__":
    main()
"})
